<script lang="ts">
 import {gameCommands,gameState} from '$lib/application/game-store'; import {BUILDINGS,CRAFT_RECIPES,COOK_RECIPES} from '$lib/content/production';
 export let close:()=>void; let tab:'build'|'craft'|'cook'='build'; let building='workshop'; let x=0; let y=0; const cells=[...Array(96).keys()];
</script>
<div class="modal" role="dialog" aria-modal="true"><section><button class="close" on:click={close}>×</button><nav><button class:active={tab==='build'} on:click={()=>tab='build'}>Bangunan</button><button class:active={tab==='craft'} on:click={()=>tab='craft'}>Crafting</button><button class:active={tab==='cook'} on:click={()=>tab='cook'}>Memasak</button></nav>
{#if tab==='build'}<h2>Bangun & Tata Kebun</h2><div class="placement"><select bind:value={building}>{#each Object.values(BUILDINGS) as item}<option value={item.id}>{item.name}</option>{/each}</select><label>X <input type="number" min="0" max="11" bind:value={x}></label><label>Y <input type="number" min="0" max="7" bind:value={y}></label><button on:click={()=>gameCommands.placeBuilding(building,x,y)}>Tempatkan</button></div><div class="grid">{#each cells as index}<i class:occupied={$gameState.buildings.some((item)=>{const d=BUILDINGS[item.type];const cx=index%12,cy=Math.floor(index/12);return cx>=item.x&&cx<item.x+d.width&&cy>=item.y&&cy<item.y+d.height})}></i>{/each}</div><div class="cards">{#each $gameState.buildings as item}<article><b>{BUILDINGS[item.type].name} Lv.{item.level}</b><span>({item.x},{item.y})</span><button on:click={()=>gameCommands.upgradeBuilding(item.id)}>Upgrade</button><button on:click={()=>gameCommands.relocateBuilding(item.id,(item.x+1)%12,item.y)}>Geser →</button></article>{/each}</div>
{:else if tab==='craft'}<h2>Produksi</h2><div class="cards">{#each Object.values(CRAFT_RECIPES) as recipe}<article><b>{recipe.name}</b><span>{Object.entries(recipe.ingredients).map(([id,q])=>`${q} ${id}`).join(' + ')} · {recipe.days} hari</span><button on:click={()=>gameCommands.craft(recipe.id)}>Produksi</button></article>{/each}</div><h3>ANTREAN</h3><div class="cards">{#each $gameState.productionQueue as job}<article><b>{CRAFT_RECIPES[job.recipeId].name}</b><span>{job.collected?'Diambil':$gameState.day>=job.readyDay?'Siap':'Hari '+job.readyDay}</span><button disabled={job.collected||$gameState.day<job.readyDay} on:click={()=>gameCommands.collectCraft(job.id)}>Ambil</button></article>{/each}</div>
{:else}<h2>Dapur Nusantara</h2><div class="cards recipes">{#each Object.values(COOK_RECIPES) as recipe}<article><b>{recipe.name}</b><span>{Object.entries(recipe.ingredients).map(([id,q])=>`${q} ${id}`).join(' + ')}</span><button on:click={()=>gameCommands.cook(recipe.id)}>Masak</button><button disabled={!$gameState.inventory[recipe.output]} on:click={()=>gameCommands.eat(recipe.id)}>Makan +{recipe.stamina}</button></article>{/each}</div>{/if}</section></div>
<style>.modal{position:fixed;z-index:20;inset:0;background:#071a16dd;display:grid;place-items:center;padding:15px}section{position:relative;width:min(780px,100%);max-height:92vh;overflow:auto;padding:25px;background:#e9dfba;color:#203c35;border:8px double #6e5037}.close{position:absolute;right:8px;top:6px;border:0;background:none;font-size:1.6rem}nav{display:flex;gap:6px}nav button,.placement button{padding:9px;background:#d1c59f;border:2px solid #80653c}nav button.active{background:#315d4b;color:white}h2{font:900 2rem Georgia}.placement{display:flex;gap:7px;flex-wrap:wrap}.placement select,.placement input{padding:7px;max-width:140px}.grid{display:grid;grid-template-columns:repeat(12,1fr);aspect-ratio:12/8;margin:15px 0;background:#729453;border:4px solid #624b32}.grid i{border:1px solid #44683a}.grid i.occupied{background:#bf874f}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.cards article{display:grid;gap:6px;padding:10px;background:#fff8dd;border:2px solid #927340}.cards span{font-size:.68rem}.cards button{padding:6px;background:#315d4b;color:white;border:0}.cards button:disabled{opacity:.4}@media(max-width:560px){.cards{grid-template-columns:1fr}}</style>
